import React, { useState } from 'react';
import './ProfilePage.css'; // Make sure to create this CSS file with the styles below

const ProfilePage = () => {
  const [skills, setSkills] = useState(['', '', '']);
  const [bio, setBio] = useState('');
  const [cv, setCv] = useState(null);
  const [rating] = useState(4.5); // This would come from your database
  const [coins] = useState(100); // This would also come from your database

  const handleSkillChange = (index, value) => {
    const newSkills = [...skills];
    newSkills[index] = value;
    setSkills(newSkills);
  };

  const handleCvUpload = (event) => {
    setCv(event.target.files[0]);
  };

  const handleDeleteAccount = () => {
    // Logic to delete account
    alert('Account deleted');
  };

  return (
    <div className="profile-page">
      <div className="header">
        <div className="progress-bar" style={{ width: '70%' }}></div>
        <div className="coins-display">{coins} Coins</div>
      </div>
      <div className="user-image">
        <img src="path_to_user_image.jpg" alt="User" />
      </div>
      <h1 className="user-name">User Name</h1>
      <div className="details-section">
        <h2>Main Skills</h2>
        {skills.map((skill, index) => (
          <input
            key={index}
            type="text"
            placeholder={`Skill ${index + 1}`}
            value={skill}
            onChange={(e) => handleSkillChange(index, e.target.value)}
          />
        ))}
        <h2>Details About You</h2>
        <textarea
          placeholder="Tell us about yourself"
          value={bio}
          onChange={(e) => setBio(e.target.value)}
        />
        <h2>Upload CV</h2>
        <input type="file" accept=".pdf,.doc,.docx" onChange={handleCvUpload} />
        <button className="action-button">Submit CV</button>
        <h2>Your Rating: {rating}</h2>
        <button className="delete-account-button" onClick={handleDeleteAccount}>
          Delete Account
        </button>
      </div>
    </div>
  );
};

export default ProfilePage;
